#!/usr/bin/env python3
"""Street Legends frontend: Activity Center Pop Shot arcade cabinet.

The user's Pop-A-Shot cabinet picture becomes a fixture in the
activity-center hall; tapping it opens Pop Shot (solo 60-second time
attack). Pop Shot is NOT in the parks — activity centers only.

What this does (frontend; the backend patch extends the layout clamp):
  1. CABINET PICTURE ASSET: writes the transparent cutout of the
     user's cabinet picture (201x400) to
     frontend/assets/activity-center/pop-shot-cabinet.png from an
     embedded base64 blob (the picture's black background was
     flood-filled to transparent and the crop trimmed to the cabinet).
     If the asset already exists at the right size, it is left alone.
  2. POP SHOT MODAL: a full-screen PopShotCenterModal (same pattern
     as the park game modals — header "POP SHOT" + red CLOSE,
     PoolWebView with POP_SHOT_HTML, onMessage 'close' closes it).
     Solo game, no PvC/PvP menu — tap the cabinet and you play.
  3. CABINET IN THE SCENE: the cabinet renders as its actual picture
     (150x300, resizeMode "contain") in the SAME horizontal ScrollView
     scene as the other six fixtures, at its own stored fractional
     position. Default {x:0.85, y:0.175} — top-right corner, the
     remaining free space (dartboard {0.5, 0.28}, card {0.85, 0.5},
     chess {0.85, 0.85}). No menu card, no shop/catalog entry.
  4. TAP = POP SHOT: tapping the cabinet opens the Pop Shot modal.
  5. HOLD-DRAG = ARRANGE (Veno only): same interaction as the other
     six fixtures — press-and-HOLD (250ms), then drag (gold border
     while dragging, scene scroll disabled while dragging); tap
     (<12px) opens the game instead. The hint renders only for
     Mayor Veno; for anyone else all seven fixtures are fixed and
     hold does nothing (tap still opens the game).
  6. MERGED LAYOUT SAVE: the six-fixture merged save is replaced by
     ONE shared save that always sends the FULL layout {pool_table,
     dart_board, card_table, dominoes, scrabble, chess_checkers,
     pop_shot} (all seven positions). Saving any one fixture never
     wipes the others' spots. A 403 snaps ALL SEVEN fixtures back.
     The modal loads all seven stored positions on open.

UNCHANGED: the six fixtures (pictures, menus, hold-drag, positions),
"Inside now" list, LEAVE, presence, the layout endpoint + its
permission, the Pop Shot game itself (PopShotHtml.ts).

Run from /app: python3 frontend/patch-activity-center-pop-shot-frontend.py
Frontend / Expo Go only. Run AFTER the Pop Shot HTML patch (which
writes PopShotHtml.ts) and after the Pop Shot backend patch is
Published (the merged save needs the seven-key clamp live first).
Requires the chess fixture live (it anchors on the chess pieces).
Idempotent: a full re-run prints ACTIVITY_CENTER_POP_SHOT_ALREADY_APPLIED.
"""
import base64
import re
import sys
from pathlib import Path

ROOT = Path(sys.argv[1]) if len(sys.argv) > 1 else Path("/app")
IDX = ROOT / "frontend/app/(tabs)/index.tsx"
API = ROOT / "frontend/services/api.ts"
ASSET = ROOT / "frontend/assets/activity-center/pop-shot-cabinet.png"
MARKER = "ACTIVITY_CENTER_POP_SHOT_OK"
VENO_ID = "3872dca3-bf7d-4807-8fc5-47c22ba67620"

CABINET_B64 = """"""

SCR_STATE_ANCHOR = "  const [centerScrDrag, setCenterScrDrag] = useState(false);"
PRESENCE_EFFECT_CLOSE = "  }, [activeCenter?.id, playerId]);"
SAVE_6 = "      await saveCenterLayout(activeCenter.id, playerId, { pool_table: centerPosToStored(centerPoolPosRef.current), dart_board: centerPosToStored(centerDartPosRef.current), card_table: centerPosToStored(centerCardPosRef.current), dominoes: centerPosToStored(centerDomPosRef.current), scrabble: centerPosToStored(centerScrPosRef.current), chess_checkers: centerPosToStored(centerChessPosRef.current) });"
SAVE_7 = "      await saveCenterLayout(activeCenter.id, playerId, { pool_table: centerPosToStored(centerPoolPosRef.current), dart_board: centerPosToStored(centerDartPosRef.current), card_table: centerPosToStored(centerCardPosRef.current), dominoes: centerPosToStored(centerDomPosRef.current), scrabble: centerPosToStored(centerScrPosRef.current), chess_checkers: centerPosToStored(centerChessPosRef.current), pop_shot: centerPosToStored(centerPopShotPosRef.current) });"
BACK_5 = """        const back = storedToCenterPos((activeCenter as any)?.layout?.pool_table);
        const backDart = storedToCenterDartPos((activeCenter as any)?.layout?.dart_board);
        centerPoolPosRef.current = back;
        setCenterPoolPos(back);
        centerDartPosRef.current = backDart;
        setCenterDartPos(backDart);
        const backCard = storedToCenterCardPos((activeCenter as any)?.layout?.card_table);
        centerCardPosRef.current = backCard;
        setCenterCardPos(backCard);
        const backDom = storedToCenterDomPos((activeCenter as any)?.layout?.dominoes);
        centerDomPosRef.current = backDom;
        setCenterDomPos(backDom);
        const backScr = storedToCenterScrPos((activeCenter as any)?.layout?.scrabble);
        centerScrPosRef.current = backScr;
        setCenterScrPos(backScr);"""
BACK_CHESS_LINES = """        const backChess = storedToCenterChessPos((activeCenter as any)?.layout?.chess_checkers);
        centerChessPosRef.current = backChess;
        setCenterChessPos(backChess);"""
BACK_PS_LINES = """        const backPs = storedToCenterPopShotPos((activeCenter as any)?.layout?.pop_shot);
        centerPopShotPosRef.current = backPs;
        setCenterPopShotPos(backPs);"""
RESPONDER_TAIL = """        if (centerDragMovedRef.current) { saveCenterLayoutNowRef.current(); }
      },
    });
  }"""
SCR_LOAD_BLOCK = """    const posScr = storedToCenterScrPos((activeCenter as any)?.layout?.scrabble);
    centerScrPosRef.current = posScr;
    setCenterScrPos(posScr);
    setCenterScrDrag(false);"""
CHESS_LOAD_LINES = """    const posChess = storedToCenterChessPos((activeCenter as any)?.layout?.chess_checkers);
    centerChessPosRef.current = posChess;
    setCenterChessPos(posChess);
    setCenterChessDrag(false);"""
PS_LOAD_LINES = """    const posPs = storedToCenterPopShotPos((activeCenter as any)?.layout?.pop_shot);
    centerPopShotPosRef.current = posPs;
    setCenterPopShotPos(posPs);
    setCenterPopShotDrag(false);"""
HINT_6 = "Hold the pool table, dartboard, card table, dominoes table, Scrabble table, or chess and checkers table to move it — swipe the room to look around."
HINT_7 = "Hold the pool table, dartboard, card table, dominoes table, Scrabble table, chess and checkers table, or Pop Shot cabinet to move it — swipe the room to look around."
CABINET_REQUIRE = "require('../../assets/activity-center/pop-shot-cabinet.png')"
IMPORT_LINE = "import { POP_SHOT_HTML } from '../../components/PopShotHtml';"
MAPSCREEN_ANCHOR = "export default function MapScreen() {"
TOP_IMPORT_RE = re.compile(r"^import[^\n]*;\s*$", re.M)

POP_SHOT_STATE_BLOCK = """
  // ACTIVITY_CENTER_POP_SHOT: hold-drag arrange (Veno only), tap = Pop Shot game.
  // Default {x:0.85, y:0.175} — top-right corner, the remaining free
  // space (dartboard {0.5, 0.28}, card {0.85, 0.5}, chess {0.85, 0.85}).
  // Shares the v2 hold/drag refs and the MERGED save (one call sends all
  // seven fixtures' positions). Size 150x300 (the cabinet is a tall
  // portrait picture, 201x400); the other fixtures are landscape.
  const [centerPopShotPos, setCenterPopShotPos] = useState({ x: 0.85, y: 0.175 });
  const [centerPopShotDrag, setCenterPopShotDrag] = useState(false);
  const centerPopShotPosRef = useRef({ x: 0.85, y: 0.175 });
  const centerPopShotResponder = useRef<any>(null);
  const storedToCenterPopShotPos = (l: any) => {
    if (!l || typeof l.x !== 'number' || typeof l.y !== 'number') return { x: 0.85, y: 0.175 };
    return storedToCenterPos(l);
  };"""

POP_SHOT_RESPONDER_BLOCK = """
  if (!centerPopShotResponder.current) {
    centerPopShotResponder.current = PanResponder.create({
      onStartShouldSetPanResponder: () => true,
      onMoveShouldSetPanResponder: () => true,
      onPanResponderGrant: () => {
        setCenterSceneScrollEnabled(false);
        centerHoldStartRef.current = Date.now();
        centerDragStartRef.current = { ...(centerPopShotPosRef.current || { x: 0.85, y: 0.175 }) };
        centerDragMovedRef.current = false;
      },
      onPanResponderMove: (evt: any, gesture: any) => {
        if (centerCtxRef.current.playerId !== CENTER_ARRANGE_OWNER_ID) return;
        if (Date.now() - centerHoldStartRef.current < 250) return;
        const s = centerDragStartRef.current || { x: 0.85, y: 0.175 };
        const nx = Math.min(0.94, Math.max(0.06, s.x + gesture.dx / centerSceneWRef.current));
        const ny = Math.min(0.94, Math.max(0.06, s.y + gesture.dy / centerSceneHRef.current));
        centerDragMovedRef.current = true;
        centerPopShotPosRef.current = { x: nx, y: ny };
        setCenterPopShotPos({ x: nx, y: ny });
        setCenterPopShotDrag(true);
        setCenterLayoutDirty(true);
      },
      onPanResponderRelease: (evt: any, gesture: any) => {
        setCenterSceneScrollEnabled(true);
        setCenterPopShotDrag(false);
        const tapDist = Math.hypot(gesture.dx || 0, gesture.dy || 0);
        if (tapDist < 12) { setPopShotCenterOpen(true); return; }
        if (centerDragMovedRef.current) { saveCenterLayoutNowRef.current(); }
      },
      onPanResponderTerminate: () => {
        setCenterSceneScrollEnabled(true);
        setCenterPopShotDrag(false);
        if (centerDragMovedRef.current) { saveCenterLayoutNowRef.current(); }
      },
    });
  }"""

POP_SHOT_LOAD_EFFECT = """
  // ACTIVITY_CENTER_POP_SHOT: load this center's stored Pop Shot spot when it opens.
  useEffect(() => {
    const posPs = storedToCenterPopShotPos((activeCenter as any)?.layout?.pop_shot);
    centerPopShotPosRef.current = posPs;
    setCenterPopShotPos(posPs);
    setCenterPopShotDrag(false);
  }, [activeCenter?.id]);"""

GAME_MODAL = """const PopShotCenterModal = ({ visible, onClose }: { visible: boolean; onClose: () => void }) => {
  return (
    <Modal visible={visible} animationType="slide" onRequestClose={onClose}>
      <View style={{ flex: 1, backgroundColor: '#111111' }}>
        <View style={{ flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center', padding: 12 }}>
          <Text style={{ color: '#ffffff', fontWeight: '800', fontSize: 16 }}>POP SHOT</Text>
          <TouchableOpacity onPress={onClose} style={{ backgroundColor: '#e74c3c', paddingVertical: 8, paddingHorizontal: 14, borderRadius: 8 }}>
            <Text style={{ color: '#ffffff', fontWeight: '800' }}>CLOSE</Text>
          </TouchableOpacity>
        </View>
        {PoolWebView ? (
          <PoolWebView
            source={{ html: POP_SHOT_HTML }}
            javaScriptEnabled={true}
            domStorageEnabled={true}
            allowsInlineMediaPlayback={true}
            mediaPlaybackRequiresUserAction={false}
            originWhitelist={['*']}
            style={{ flex: 1 }}
            onMessage={(event: any) => { if (event?.nativeEvent?.data === 'close') onClose(); }}
          />
        ) : (
          <Text style={{ color: '#ffffff', textAlign: 'center', marginTop: 40 }}>Pop Shot needs WebView, which is not available in this build.</Text>
        )}
      </View>
    </Modal>
  );
}"""

# __PS_ART_REQUIRE__ is replaced with the resolved cabinet require.
POP_SHOT_VIEW = """
              <View
                {...(centerPopShotResponder.current ? centerPopShotResponder.current.panHandlers : {})}
                style={{ position: 'absolute', left: centerPopShotPos.x * centerSceneW - 75, top: centerPopShotPos.y * centerSceneH - 150, width: 150, height: 300, borderWidth: centerPopShotDrag ? 3 : 0, borderColor: '#ffd54f', borderRadius: 8 }}
              >
                <Image source={__PS_ART_REQUIRE__} style={{ width: 150, height: 300, borderRadius: 8 }} resizeMode="contain" />
              </View>"""


def _balance(s):
    return (s.count("{") - s.count("}"), s.count("(") - s.count(")"),
            s.count("[") - s.count("]"))


def main():
    if not IDX.exists():
        print("WARNING: index.tsx not found - Pop Shot cabinet NOT added")
        return 1
    src = IDX.read_text(errors="ignore")
    asrc = API.read_text(errors="ignore") if API.exists() else ""
    orig = _balance(src)
    landed = []
    warnings = []
    changed = False

    # ---- Idempotency: Pop Shot cabinet already landed. ----
    if "ACTIVITY_CENTER_POP_SHOT" in src and "centerPopShotPos" in src:
        print("ACTIVITY_CENTER_POP_SHOT_ALREADY_APPLIED")
        return 0

    # ---- Preconditions: the v2 room + chess table + PopShotHtml + save fn. ----
    if "centerSceneScrollEnabled" not in src or "ACTIVITY_CENTER_POOL_V2" not in src:
        print("WARNING: v2 center room not found - run the pool-table v2 patch first, Pop Shot cabinet NOT added")
        return 1
    if "centerChessPos" not in src or "ACTIVITY_CENTER_CHESS" not in src:
        print("WARNING: chess table not found - run the chess frontend patch first, Pop Shot cabinet NOT added")
        return 1
    if "saveCenterLayout" not in src:
        print("WARNING: v2 layout save not found - run the pool-table v2 patch first, Pop Shot cabinet NOT added")
        return 1
    if "PoolWebView" not in src:
        print("WARNING: PoolWebView not found in index.tsx - Pop Shot cabinet NOT added")
        return 1

    # ---- Piece 0: write the cabinet picture asset (base64 -> PNG). ----
    try:
        raw = base64.b64decode(CABINET_B64)
    except Exception as e:
        print("WARNING: cabinet base64 did not decode (%s) - Pop Shot cabinet NOT added" % e)
        return 1
    if not raw.startswith(b"\x89PNG"):
        print("WARNING: cabinet blob is not a PNG - Pop Shot cabinet NOT added")
        return 1
    if ASSET.exists() and ASSET.stat().st_size == len(raw):
        print("ACTIVITY_CENTER_POP_SHOT_ASSET_ALREADY_APPLIED")
        landed.append("asset")
    else:
        ASSET.parent.mkdir(parents=True, exist_ok=True)
        ASSET.write_bytes(raw)
        print("ACTIVITY_CENTER_POP_SHOT_ASSET_OK (%d bytes -> %s)" % (len(raw), ASSET))
        landed.append("asset")

    # ---- Piece 1: import POP_SHOT_HTML (after the last import). ----
    if "POP_SHOT_HTML" in src and "from '../../components/PopShotHtml'" in src:
        print("ACTIVITY_CENTER_POP_SHOT_IMPORT_ALREADY_APPLIED")
        landed.append("import")
    else:
        imports = list(TOP_IMPORT_RE.finditer(src))
        if not imports:
            print("WARNING: no import lines found - POP_SHOT_HTML import NOT added")
            return 1
        last = imports[-1]
        src = src[:last.end()] + "\n" + IMPORT_LINE + src[last.end():]
        changed = True
        print("ACTIVITY_CENTER_POP_SHOT_IMPORT_OK")
        landed.append("import")

    # ---- Piece 2: PopShotCenterModal component (before MapScreen anchor). ----
    if "const PopShotCenterModal" in src:
        print("ACTIVITY_CENTER_POP_SHOT_MODAL_ALREADY_APPLIED")
        landed.append("modal")
    elif src.count(MAPSCREEN_ANCHOR) == 1:
        src = src.replace(MAPSCREEN_ANCHOR, GAME_MODAL + "\n\n" + MAPSCREEN_ANCHOR, 1)
        changed = True
        print("ACTIVITY_CENTER_POP_SHOT_MODAL_OK")
        landed.append("modal")
    else:
        print("WARNING: MapScreen anchor matched %dx - Pop Shot modal NOT added" % src.count(MAPSCREEN_ANCHOR))
        return 1

    # ---- Piece 3: Pop Shot state (positions, refs, loader). ----
    if "ACTIVITY_CENTER_POP_SHOT: hold-drag arrange" in src:
        print("ACTIVITY_CENTER_POP_SHOT_STATE_ALREADY_APPLIED")
        landed.append("state")
    elif src.count(SCR_STATE_ANCHOR) == 1:
        src = src.replace(SCR_STATE_ANCHOR, SCR_STATE_ANCHOR + POP_SHOT_STATE_BLOCK, 1)
        changed = True
        print("ACTIVITY_CENTER_POP_SHOT_STATE_OK")
        landed.append("state")
    else:
        print("WARNING: Scrabble state anchor matched %dx - Pop Shot state NOT added" % src.count(SCR_STATE_ANCHOR))
        return 1

    # ---- Piece 4: MERGED save — one call sends ALL SEVEN fixtures (hard gate). ----
    back6 = BACK_5 + "\n" + BACK_CHESS_LINES
    if "pop_shot: centerPosToStored(centerPopShotPosRef.current)" in src:
        print("ACTIVITY_CENTER_POP_SHOT_SAVE_ALREADY_APPLIED")
        landed.append("save")
    elif src.count(SAVE_6) == 1 and src.count(back6) == 1:
        src = src.replace(SAVE_6, SAVE_7, 1)
        src = src.replace(back6, back6 + "\n" + BACK_PS_LINES, 1)
        changed = True
        print("ACTIVITY_CENTER_POP_SHOT_SAVE_OK (merged: pool + dart + card + dominoes + scrabble + chess + pop shot in one call)")
        landed.append("save")
    else:
        print("WARNING: merged save lines not matched (save=%dx back=%dx) - merged save NOT wired; Pop Shot cabinet NOT added (a Pop Shot save would drop the other six spots)" % (src.count(SAVE_6), src.count(back6)))
        return 1

    # ---- Piece 5: Pop Shot responder (hold-drag), after the LAST responder (the chess one). ----
    if "centerPopShotResponder.current = PanResponder.create" in src:
        print("ACTIVITY_CENTER_POP_SHOT_RESPONDER_ALREADY_APPLIED")
        landed.append("responder")
    else:
        tail_idx = src.rfind(RESPONDER_TAIL)
        if tail_idx == -1:
            print("WARNING: responder tail not found - Pop Shot responder NOT added")
            return 1
        tail_end = tail_idx + len(RESPONDER_TAIL)
        src = src[:tail_end] + POP_SHOT_RESPONDER_BLOCK + src[tail_end:]
        changed = True
        print("ACTIVITY_CENTER_POP_SHOT_RESPONDER_OK")
        landed.append("responder")

    # ---- Piece 6: load the stored Pop Shot spot when a center opens. ----
    chess_load = SCR_LOAD_BLOCK + "\n" + CHESS_LOAD_LINES
    if "const posPs = storedToCenterPopShotPos" in src:
        print("ACTIVITY_CENTER_POP_SHOT_LOAD_ALREADY_APPLIED")
        landed.append("load")
    elif src.count(chess_load) == 1:
        src = src.replace(chess_load, chess_load + "\n" + PS_LOAD_LINES, 1)
        changed = True
        print("ACTIVITY_CENTER_POP_SHOT_LOAD_OK (chess load extended)")
        landed.append("load")
    elif src.count(PRESENCE_EFFECT_CLOSE) == 1:
        src = src.replace(PRESENCE_EFFECT_CLOSE, PRESENCE_EFFECT_CLOSE + POP_SHOT_LOAD_EFFECT, 1)
        changed = True
        print("ACTIVITY_CENTER_POP_SHOT_LOAD_OK (standalone load effect)")
        landed.append("load")
    else:
        print("WARNING: load anchors matched 0x - stored Pop Shot spot NOT loaded (cabinet will sit at the default spot)")
        warnings.append("load")

    # ---- Piece 7: center modal open state. ----
    if "const [popShotCenterOpen, setPopShotCenterOpen]" in src:
        print("ACTIVITY_CENTER_POP_SHOT_MODAL_STATE_ALREADY_APPLIED")
        landed.append("modal-state")
    else:
        chess_center_line = None
        for ln in src.split("\n"):
            if "chessMenuCenterOpen" in ln and "useState" in ln:
                chess_center_line = ln
                break
        if chess_center_line is not None:
            src = src.replace(chess_center_line, chess_center_line + "\n  const [popShotCenterOpen, setPopShotCenterOpen] = useState(false);", 1)
            changed = True
            print("ACTIVITY_CENTER_POP_SHOT_MODAL_STATE_OK")
            landed.append("modal-state")
        elif src.count("const [poolMenuCenterOpen, setPoolMenuCenterOpen]") == 1:
            src = src.replace("const [poolMenuCenterOpen, setPoolMenuCenterOpen]",
                              "const [poolMenuCenterOpen, setPoolMenuCenterOpen]\n  const [popShotCenterOpen, setPopShotCenterOpen] = useState(false);", 1)
            changed = True
            print("ACTIVITY_CENTER_POP_SHOT_MODAL_STATE_OK (fallback anchor)")
            landed.append("modal-state")
        else:
            print("WARNING: Pop Shot modal state anchor not found - center modal state NOT added")
            return 1

    # ---- Piece 8: center render of the Pop Shot modal (after the chess center render). ----
    if "PopShotCenterModal visible={popShotCenterOpen}" in src:
        print("ACTIVITY_CENTER_POP_SHOT_RENDER_ALREADY_APPLIED")
        landed.append("render")
    else:
        lines = src.split("\n")
        chess_idx = None
        for i, ln in enumerate(lines):
            if "ChessCheckersTableMenuModal visible={chessMenuCenterOpen}" in ln:
                chess_idx = i
                break
        if chess_idx is None:
            print("WARNING: chess center render not found - Pop Shot modal render NOT added")
            return 1
        render_block = "      {popShotCenterOpen ? (<PopShotCenterModal visible={popShotCenterOpen} onClose={() => setPopShotCenterOpen(false)} />) : null}"
        lines = lines[:chess_idx + 1] + [render_block] + lines[chess_idx + 1:]
        src = "\n".join(lines)
        changed = True
        print("ACTIVITY_CENTER_POP_SHOT_RENDER_OK")
        landed.append("render")

    # ---- Piece 9: cabinet picture in the scene, after the chess table. ----
    if "centerPopShotResponder.current.panHandlers" in src:
        print("ACTIVITY_CENTER_POP_SHOT_PICTURE_ALREADY_APPLIED")
        landed.append("picture")
    else:
        ph = src.find("centerChessResponder.current.panHandlers")
        if ph == -1:
            print("WARNING: chess table picture not found in scene - Pop Shot picture NOT added")
            return 1
        view_close = src.find("</View>", ph)
        if view_close == -1:
            print("WARNING: chess table view close not found - Pop Shot picture NOT added")
            return 1
        view = POP_SHOT_VIEW.replace("__PS_ART_REQUIRE__", CABINET_REQUIRE)
        src = src[:view_close + len("</View>")] + view + src[view_close + len("</View>"):]
        changed = True
        print("ACTIVITY_CENTER_POP_SHOT_PICTURE_OK")
        landed.append("picture")

    # ---- Piece 10: hint now names all seven fixtures (best effort). ----
    if HINT_7 in src:
        print("ACTIVITY_CENTER_POP_SHOT_HINT_ALREADY_APPLIED")
        landed.append("hint")
    elif src.count(HINT_6) == 1:
        src = src.replace(HINT_6, HINT_7, 1)
        changed = True
        print("ACTIVITY_CENTER_POP_SHOT_HINT_OK")
        landed.append("hint")
    else:
        print("NOTE: Veno hint matched 0x - hint stays as-is")

    # ---- api.ts sanity: the layout save fn must exist (v2's piece). ----
    if asrc and "export const saveCenterLayout" not in asrc:
        print("WARNING: saveCenterLayout missing in api.ts - drag will move locally only (v2 api piece did not land)")
        warnings.append("api")

    if _balance(src) != orig:
        print("WARNING: balance changed - index.tsx NOT written")
        return 1
    if not landed:
        print("ACTIVITY_CENTER_POP_SHOT_PARTIAL: nothing landed")
        return 1
    if not changed:
        print("ACTIVITY_CENTER_POP_SHOT_ALREADY_APPLIED")
        return 0
    IDX.write_text(src)
    if warnings:
        print("ACTIVITY_CENTER_POP_SHOT_PARTIAL: " + ",".join(landed) + " (warnings: " + ",".join(warnings) + ")")
    else:
        print(MARKER)
    return 0


if __name__ == "__main__":
    sys.exit(main())
